// Mandated locations and test files are two of the doc's three exemptions: their long
// references are forced by a tool contract or a test-location convention.
const EXEMPT_SOURCE = (file) =>
  file.startsWith('.github/') || file.startsWith('.claude/') ||
  /(^|\/)(test|tests|__tests__|spec)\//.test(file) || /\.(test|spec)\./.test(file);

// The third exemption is the plugin-contract one, and unlike the two above it is a
// property of the reference, not of the source file: a pack's check module must import
// the engine's checks lib to emit a finding at all, and neither end of that reference
// can move. The pack loader discovers packs at fixed paths (packs/, .claudinite/local/
// packs/), and under a consumer's mount the lib is vendored canon the project doesn't
// own to restructure. So the distance is fixed by the contract, not chosen: 5 from a
// pack in the canon home, 7 from a local pack beside a consumer's shared mount. Every
// pack rule ever written takes it, which is what makes it structural rather than a
// placement to fix. One-directional like the mandated-location exemption — ordinary
// code reaching *into* a pack is still a smell, and so is a pack reaching anywhere else.
const PACK_MODULE = /^(?:packs|skills)\/|^\.claudinite\/(?:local\/packs|local_packs)\//;
const ENGINE_CHECKS_LIB = /^(?:\.claudinite\/shared\/)?engine\/checks\/helpers\//;
const EXEMPT_REF = (file, resolved) =>
  PACK_MODULE.test(file) && ENGINE_CHECKS_LIB.test(resolved);

